pub fn setbit(t: Rc<Array<u64>>, v: u64) -> Rc<Array<u64>> {
  let a = div(v, 63u64);
  let tmp = rocq_array::get::<u64>(&t, a);
  rocq_array::set::<u64>(t, a, lor(tmp, lsl(1u64, mod_(v, 63u64))))
}

